/** @jsxImportSource solid-js */
import { onMount, onCleanup, createEffect } from "solid-js";
import { mountCollectionLayoutMorph, type CollectionLayoutMorphOptions } from "../../components/collection-layout-morph/CollectionLayoutMorphEngine.js";
import type { MotionController } from "../../components/collection-layout-morph/motion-runtime";

export function CollectionLayoutMorph(props: { options?: CollectionLayoutMorphOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountCollectionLayoutMorph(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="collection-layout-morph" />;
}

